  var wg sync.WaitGroup
  ch := make(chan uint64, 1000)
  for i := 0; i < 4; i++ {
    wg.Add(1)
    go func() {
      defer wg.Done()
      for j := 0; j < 1000; j++ {
        v, _ := rng.NextRandom()
        ch <- v
      }
    }()
  }
  go func() { wg.Wait(); close(ch) }()
  var min, max uint64 = ^uint64(0), 0
